import{_ as n,o,c as h,a3 as a}from"./chunks/framework.DX_KL3e0.js";const u=JSON.parse('{"title":"Đặt phòng họp","description":"","frontmatter":{},"headers":[],"relativePath":"huong-dan/dat-phong-hop.md","filePath":"huong-dan/dat-phong-hop.md","lastUpdated":1782145431000}'),g={name:"huong-dan/dat-phong-hop.md"};function r(i,t,l,e,s,c){return o(),h("div",null,[...t[0]||(t[0]=[a('<h1 id="đat-phong-hop" tabindex="-1">Đặt phòng họp <a class="header-anchor" href="#đat-phong-hop" aria-label="Permalink to &quot;Đặt phòng họp&quot;">​</a></h1><blockquote><p><strong>🎯 Mục tiêu:</strong> Đặt một phòng họp đúng khung giờ, không trùng lịch. <strong>👤 Ai làm được:</strong> Mọi người dùng. · <strong>⏱️ Khoảng:</strong> ~2 phút.</p></blockquote><h2 id="cac-buoc" tabindex="-1">Các bước <a class="header-anchor" href="#cac-buoc" aria-label="Permalink to &quot;Các bước&quot;">​</a></h2><ol><li>Vào <strong>Đặt Phòng Họp</strong> (nhóm <em>Hoạt Động</em>) → nhấn nút <strong>đặt phòng</strong>.</li><li>Điền: <ul><li><strong>Phòng Họp</strong> — chọn phòng.</li><li><strong>Ngày Đặt Phòng</strong>, <strong>Giờ Bắt Đầu</strong> &amp; <strong>Giờ Kết Thúc</strong>.</li><li><strong>Nội Dung Cuộc Họp</strong>, <strong>Số Lượng Người Tham Dự</strong> (và chọn người tham dự nếu muốn).</li></ul></li><li>Hệ thống tự <strong>kiểm tra trùng giờ</strong> — nếu chồng lấn với lượt đặt khác cùng phòng sẽ cảnh báo.</li><li>Nhấn lưu để gửi.</li></ol><h2 id="✅-ket-qua" tabindex="-1">✅ Kết quả <a class="header-anchor" href="#✅-ket-qua" aria-label="Permalink to &quot;✅ Kết quả&quot;">​</a></h2><p>Lượt đặt hiện trên lịch với trạng thái <strong>Chờ duyệt / Đã duyệt / Từ chối</strong>. Bạn theo dõi ngay trên lịch.</p><h2 id="💡-meo-luu-y" tabindex="-1">💡 Mẹo &amp; lưu ý <a class="header-anchor" href="#💡-meo-luu-y" aria-label="Permalink to &quot;💡 Mẹo &amp; lưu ý&quot;">​</a></h2><ul><li>Bị cảnh báo trùng giờ → đổi giờ hoặc chọn phòng khác trước khi lưu.</li><li><strong>Hủy / đổi:</strong> mở chi tiết lượt đặt → <strong>Hủy</strong> (nhập lý do). Sửa lượt <strong>đã duyệt</strong> sẽ tự chuyển về <strong>Chờ duyệt</strong>.</li><li>Người tham dự và người duyệt nhận thông báo in-app + Telegram.</li></ul><p><em>Chi tiết: <a href="/help/chuc-nang/dat-phong.html">Đặt Phòng Họp</a></em></p>',9)])])}const d=n(g,[["render",r]]);export{u as __pageData,d as default};
